{"status":"candidate","chosen_option":"threshold_connectivity","assumptions":["Because no language is specified, the artifact uses C++17."],"observations":[{"statement":"The goal is to find the smallest edge-weight threshold that connects vertices 1 and n; if they never become connected, the answer is -1.","source_ids":["task"]},{"statement":"The n=1 case must output 0, and the supplied disconnected example outputs -1.","source_ids":["public1","public2"]}],"artifact":{"code":"#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
using namespace std;

struct Edge {
    int u, v;
    long long w;
};

struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n + 1), size(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    vector<Edge> edges(m);
    for (auto &e : edges) cin >> e.u >> e.v >> e.w;

    if (n == 1) {
        cout << 0 << '\n';
        return 0;
    }

    sort(edges.begin(), edges.end(), [](const Edge &a, const Edge &b) {
        return a.w < b.w;
    });

    DSU dsu(n);
    for (const auto &e : edges) {
        dsu.unite(e.u, e.v);
        if (dsu.find(1) == dsu.find(n)) {
            cout << e.w << '\n';
            return 0;
        }
    }

    cout << -1 << '\n';
    return 0;
}"}}
